/**
 * 英文字典 — 所有翻譯 key 的唯一來源(source of truth)。
 * English dictionary — the single source of truth for every translation key.
 *
 * 規則 / Rules:
 * - 新增 UI 字串:先在這裡加 key,再到 zh-TW.ts 與 ja.ts 補齊(缺 key 會編譯錯誤)。
 *   Add the key here first, then fill it in zh-TW.ts and ja.ts (missing keys fail to compile).
 * - key 用「namespace.camelCase」;namespace 對應功能區(nav / tunnels / wizard / terminal ...)。
 * - {var} 是插值佔位符,翻譯時保留;t() 填字串,tn() 可填 ReactNode(如 <code>)。
 *   {var} placeholders survive translation; t() takes strings, tn() takes ReactNodes.
 */
