    "clientIp.v.okTitle": "Telepy sees a public address: {ip}",
    "clientIp.v.okBody": "If this is the address your network uses on the internet, sign-ins and sessions are recorded correctly.",
    "clientIp.v.hopsTooLowTitle": "There is one more proxy than Telepy counts",
    "clientIp.v.hopsTooHighTitle": "Telepy counts more proxies than there are",
    "clientIp.v.hopsBody": "Set {setting} in .env and restart the backend, then check again. {auto} instead counts every internal address as a proxy, so the number never has to match.",
    "clientIp.v.useHeaderTitle": "The {header} header carries your public address",
    "clientIp.v.useHeaderBody": "Set {setting} in .env and restart the backend — but only if the proxy in front of Telepy always sets it itself; otherwise a visitor could write it.",
    "clientIp.v.headerPrivateTitle": "CLIENT_IP_HEADER gives an internal address",
    "clientIp.v.headerPrivateBody": "{header} carries {ip}. Check the proxy that sets it, or clear CLIENT_IP_HEADER.",
    "clientIp.v.allPrivateTitle": "Every address that reaches Telepy is internal",
    "clientIp.v.allPrivateBody": "The proxy in front of Telepy had already lost your address when it forwarded the request ({ip} is its own network's address). No Telepy setting can recover it: the proxy has to be fixed.",
    "clientIp.v.directBody": "No proxy put an X-Forwarded-For header on this request: it reached Telepy directly from {ip}, which is normal when you browse from Telepy's own machine or network. Visitors from the internet go through the proxy, so check again from outside.",
    "clientIp.v.unknownTitle": "Telepy cannot tell where this request came from",
    "clientIp.v.unknownBody": "No X-Forwarded-For and no connection address reached the backend.",
    "clientIp.fix.title": "How to fix the proxy in front of Telepy",
    "clientIp.fix.hostNet": "A reverse proxy in Docker (e.g. Nginx Proxy Manager) behind a published port often sees every visitor as the Docker bridge. Run it with {mode} or outside Docker so it sees real addresses.",
    "clientIp.fix.ipv6": "If visitors arrive over IPv6 while the container network is IPv4-only, Docker's userland proxy rewrites them: enable IPv6 on that network, or set {setting} in Docker's daemon.json.",
    "clientIp.fix.noCdn": "No CDN header such as {header} reached Telepy, so this request did not come through Cloudflare or another CDN. A Cloudflare record set to DNS only (grey cloud) sends visitors straight to your proxy. Leave {setting} unset then: visitors can send that header themselves.",
    "clientIp.fix.after": "Then check again here. With {setting} every internal proxy is skipped on its own; a number means exactly that many proxies in front of the backend, Traefik included.",
    "clientIp.fix.outside": "Check from outside your own network, e.g. a phone on mobile data: going out to your public address and back in, the router's NAT loopback can hand Telepy its own internal address.",
    "clientIp.shortChain": "This request passed fewer proxies than {setting}. If that is normal for your setup, lower it; otherwise a visitor who reaches Telepy this way can choose the address that gets recorded.",
    "clientIp.headerAbsent": "CLIENT_IP_HEADER is {header}, but this request does not carry it, so Telepy fell back to X-Forwarded-For.",
    "clientIp.probe.button": "Try a made-up address",
    "clientIp.probe.hint": "Sends this check again with made-up X-Forwarded-For and X-Real-IP headers. A visitor must not be able to choose the address Telepy records.",
    "clientIp.probe.safe": "Safe: Telepy ignored the made-up addresses.",
    "clientIp.probe.spoofableTitle": "A visitor can choose the address Telepy records",
    "clientIp.probe.realIp": "Telepy recorded the made-up {ip}: the proxy in front of Telepy trusts the X-Real-IP header a visitor sends (nginx real_ip, as Nginx Proxy Manager sets it up) and passes it on as the source. Make that proxy trust X-Real-IP only from your own proxies ({setting}), or turn real_ip off there.",
    "clientIp.probe.sameCause": "Same cause as above: every visitor reaches that proxy as an internal address ({ip}), and Nginx Proxy Manager trusts X-Real-IP from internal addresses by default. Once the proxy sees real addresses, this goes away too.",
    "clientIp.probe.forwardedFor": "Telepy recorded the made-up {ip} from X-Forwarded-For: {setting} counts more proxies than this request passed. Lower it.",
    "clientIp.hopsAuto": "automatic: every internal address counts as a proxy ({n} skipped on this request)",
    "clientIp.hopsFixed": "a fixed number of proxies, Traefik included",
    "clientIp.v.hopsBodyAuto": "With automatic counting a proxy with a public address is taken for the visitor. Set {setting} in .env (the proxies in front of the backend, Traefik included), restart the backend, then check again.",
    "clientIp.probe.autoInternalTitle": "A visitor on an internal network can choose their own recorded address",
    "clientIp.probe.autoInternal": "Telepy recorded the made-up {ip}: you are browsing from an internal address, and with {setting} every internal address counts as a proxy, so yours was skipped. Visitors from the internet cannot do this, and someone on an internal network only changes what is recorded about themselves. To rule it out, set {fixed} to the number of proxies in front of the backend.",
