    "wizard.accounts.nextReauth": "Next: authorize again",
    "wizard.authorize.rerunAccounts": "Since you last ran this, {names} was added. Log in to the device as that account and run the command below again.",
    "wizard.authorize.rerunKeys": "The keys in this command changed since you last ran it. Run it again on the device.",
    "wizard.authorize.new": "new",
    "wizard.authorize.doneAgain": "I've run it again",
    // 為什麼 / Why
    "wizard.why.title": "Why this step?",
    "wizard.why.device": "Your device connects out to Telepy, not the other way round, so it needs no public IP and no open port. Telepy only lets in devices whose key it knows.",
    "wizard.why.devicePoint1": "Your private network already isolates the device well: nothing outside can reach it. Telepy keeps that. No port is opened; the device only makes one outgoing connection.",
    "wizard.why.devicePoint2": "This key can only open this tunnel, so a leaked key can't reach your other devices.",
    "wizard.why.devicePoint3": "Telepy reserves a private port for the device when you continue.",
    "wizard.why.accounts": "Telepy logs in to the device as a real OS account. Everyone you share this tunnel with comes in with the same Telepy key, so this list is what limits which accounts can be used.",
    "wizard.why.accountsPoint1": "Use accounts that really exist on the device. Not sure? Run whoami there.",
    "wizard.why.accountsPoint2": "People you share the tunnel with only get the accounts you give them later.",
    "wizard.why.accountsPoint3": "You can change the list anytime from the tunnel's menu.",
    "wizard.why.authorize": "The web terminal, file manager and remote browser reach the device by logging in to its own sshd through the tunnel. sshd only accepts keys listed in authorized_keys.",
    "wizard.why.authorizePoint1": "Telepy's service key powers the web terminal, files, remote browser and AI sessions.",
    "wizard.why.authorizePoint2": "Your own keys let you ssh from your laptop. If you chose to install your keys, Telepy adds them for you after this step.",
    "wizard.why.authorizePoint3": "The command only appends. Existing keys stay, and running it again adds nothing twice.",
    "wizard.why.connect": "The device dials out to Telepy and keeps that connection open. That outgoing link is the tunnel, which is why it works behind NAT and firewalls.",
    "wizard.why.connectPoint1": "The quick test stops when you close the terminal you ran it in.",
    "wizard.why.connectPoint2": "AutoSSH, the systemd service and Docker reconnect on their own. Use one of them for anything long-lived.",
    "wizard.why.connectPoint3": "The status turns green as soon as the device connects. No need to refresh.",
    "wizard.why.verify": "Telepy now logs in as each account through the tunnel, the same way the web terminal does, so problems show up now rather than later.",
    "wizard.why.verifyPoint1": "A refused login almost always means the key isn't in that account's authorized_keys.",
    "wizard.why.verifyPoint2": "Offline? Check that the command from step 4 is still running on the device.",
    "wizard.why.verifyPoint3": "Fixed something? Re-check. Nothing needs to be recreated.",
    // Step 1：裝置 / Device
    "wizard.device.title": "Which device are you connecting?",
    "wizard.device.subtitle": "Paste the device's SSH public key, give it a name, and enter the port its sshd listens on.",
