    "mcp.title": "AI tools (MCP)",
    "mcp.subtitle": "Connect Claude Code, Claude Desktop, Cursor or any other MCP client to Telepy. It works with your permissions, and the SSH sessions it opens close by themselves.",
    "mcp.serverUrl": "Server URL",
    "mcp.serverUrlHint": "There is no token to paste. The first time a client connects, your browser opens an approval page where you choose what it may do and which tunnels it may use.",
    "mcp.setupTitle": "Set up your client",
    "mcp.clientOther": "Cursor and others",
    "mcp.claudeCodeHint": "Run this in a terminal, then type {cmd} in Claude Code and pick telepy to sign in.",
    "mcp.claudeAppStep1": "Open {path} and choose {action}.",
    "mcp.claudeAppStep2": "Paste the server URL above and save.",
    "mcp.claudeAppStep3": "Connect it; Telepy's approval page opens in your browser.",
    "mcp.otherHint": "Add this to the client's {file} (the exact file and key names vary by client).",
    "mcp.permissionsTitle": "What an app can do",
    "mcp.tokensTitle": "No browser? Use an API token",
    "mcp.tokensBody": "Headless agents and CI can skip the browser consent: send a personal API token as the Bearer header. It carries the scopes and tunnels you gave it, and revoking it cuts the agent off at once.",
    "mcp.tokensOpen": "Open API tokens",
    "mcp.permissionsHint": "You choose these on the approval page and can limit an app to some tunnels. An app never gets more than you have: it needs VIEW access to the tunnel and, on shared tunnels, may only use the usernames the owner allowed.",
    "mcp.sessionsTitle": "How sessions end",
    "mcp.ruleTimers": "A session closes after a stretch without commands, and always once it reaches its maximum lifetime.",
    "mcp.ruleShells": "Interactive shells (for TUIs and prompts) live inside a session and close with it; command rules check every Enter typed at their prompt.",
    "mcp.ruleBrowser": "A remote browser opened by an agent counts against the same limit, shows up under Live sessions and can be ended there.",
    "mcp.ruleClosed": "It also closes when you revoke the app, close it on the AI activity page, or the device goes offline.",
    "mcp.ruleLimit": "Each user can keep only a few sessions open at once, across all apps.",
    "mcp.ruleNotify": "When someone's agent connects to a shared tunnel, the tunnel's owner is notified.",
    "mcp.ruleAudit": "Every tool call is logged with the full command, so don't let an agent put passwords on the command line.",
