    // ── 站台設定的欄位說明 / Site-setting labels & descriptions ─────
    // 後端 SiteSettings 每個欄位對應 siteSettings.<欄位>.label / .description;找不到 key 時
    // 前端會退回後端 meta(help_text)。新增站台設定欄位時,記得三份字典都要補。
    // Each SiteSettings field maps to siteSettings.<field>.label/.description; the page falls
    // back to the backend meta when a key is missing. Add keys here when adding fields.
    "siteSettings.allow_registration.label": "Allow Registration",
    "siteSettings.allow_registration.description": "Whether new accounts can self-register. When off, only administrators can create accounts. Takes effect immediately.",
    "siteSettings.valid_register_domains.label": "Allowed Registration Email Domains",
    "siteSettings.valid_register_domains.description": "Comma-separated whitelist of email domains allowed to sign in with Google (e.g. gmail.com,mycorp.com). Domains must match exactly; subdomains are listed separately. Applies to new and existing accounts. Leave empty to use the system default, gmail.com. Takes effect immediately.",
    "regDomains.description": "Which email domains may sign in with Google. Applies to every Google sign-in, new accounts and existing ones alike. Password sign-in is not affected.",
    "regDomains.regOpen": "New accounts: open",
    "regDomains.regClosed": "New accounts: closed",
    "regDomains.closedNote": "Registration is closed (see the switch above). People from these domains can still sign in with Google if they already have an account, but cannot create a new one.",
    "regDomains.addLabel": "Add domains",
    "regDomains.add": "Add",
    "regDomains.addHint": "Press Enter, comma or space to add; paste a list to add many at once. An address like alice@mycorp.com is reduced to mycorp.com. Domains must match exactly: mycorp.com does not include mail.mycorp.com.",
