    "network.firstScanTip": "Start with Scan LAN on an online device: Telepy lists what it finds here, and you can label hosts and set their login.",
    "network.howItWorks": "Links show the path every connection takes: you → Telepy → the device (reverse SSH tunnel) → the LAN host (the device's sshd). Solid lines are online devices, dashed lines offline ones.",
    "join.mode.command": "One command (Linux / macOS / OpenWrt)",
    "join.mode.steps": "Step by step",
    "join.pageSubtitle": "Run one command on the device and Telepy sets up the rest. The diagram shows what is happening, and the card beside it explains why.",
    "join.title": "Add a device with one command",
    "join.subtitle": "Telepy gives you a command to paste on the device. It looks at what the device has (OpenSSH or Dropbear, procd / systemd / launchd), sets up the key, the tunnel and the service, then checks that Telepy can log in. Linux, macOS and OpenWrt routers; for Windows, use Step by step.",
    "join.nameLabel": "Device name (optional)",
    "join.namePlaceholder": "office-pi",
    "join.keyListMineHint": "Telepy puts them into the account the command runs for as soon as the device connects, so you can ssh in from your own computer.",
    "join.create": "Create the command",
    "join.tooMany": "You have too many open join commands. Use or cancel one first.",
    "join.thisDevice": "This device",
    "join.pasteTitle": "Run this on the device",
    "join.pasteSubtitle": "Open a terminal on the device (or ssh into it) and paste the command. This page follows along.",
    "join.sudoLabel": "How to install",
    "join.transportLabel": "How the device reaches Telepy",
    "join.transportSsh": "SSH port",
    "join.transportWeb": "Web port only",
    "join.transportSshHint": "The device connects to Telepy's SSH port directly (the usual way).",
    "join.transportWebHint": "For networks that only let the web port (443) out: ssh rides inside a WebSocket to Telepy. The device needs python3; the SSH session inside, its keys and host-key check are unchanged.",
    "join.doesWeb": "Downloads a small python3 program that carries the SSH connection inside a WebSocket on the web port.",
    "join.withSudo": "With sudo (recommended)",
    "join.withoutSudo": "Without sudo",
    "join.withSudoHint": "Installs a system service (systemd or launchd) that keeps the tunnel up after logouts and reboots. Telepy logs in as the account that ran sudo.",
    "join.withoutSudoHint": "Installs a user service instead; it may stop when you log out. Use this when you can't use sudo — or when you already are root, as on an OpenWrt router.",
    "join.expiresIn": "Works once · expires in {time}",
    "join.viewScript": "View the script",
    "join.whatItDoes": "What the command does",
    "join.expired": "This command has expired. Create a new one.",
    "join.step.waiting": "Waiting for the device to run the command",
    "join.step.waitingDetail": "Nothing has reached Telepy yet.",
    "join.step.registered": "Registered as {name}",
    "join.step.connected": "Tunnel connected",
    "join.step.connectedDetail": "Reverse port {port} on the Telepy server",
    "join.step.verified": "Telepy logged in as {user}",
    "join.done": "{name} is ready, and Telepy can log in as {user}. Add more accounts or share it from the tunnel list.",
    "join.failedHint": "The device is registered, but the test login did not work. Fix the cause above, then run a new command on the same device: it reuses the same tunnel.",
    "join.cancel": "Cancel the command",
    "join.another": "Add another device",
    "join.sameMachineTitle": "This is the same machine as {name}",
    "join.sameMachine": "Both tunnels reach one machine but manage their accounts and keys separately. Consider adding this account to {name} instead and removing this tunnel.",
    "join.newCommand": "Create a new command",
    "join.openTerminal": "Open terminal",
    "join.goTunnels": "Go to tunnels",
    "join.why.title": "Why one command?",
    "join.why.body": "It does what the step-by-step setup does (key, authorization, service, check) on the device itself, so nothing has to be copied back and forth.",
    "join.why.point1": "The command works once and expires after 30 minutes; it can only add a device to your account.",
    "join.why.point2": "The script only appends to authorized_keys and checks Telepy's host key; read it first with View the script.",
    "join.why.point3": "The device only dials out to Telepy; no inbound port is opened.",
    "join.howLabel": "How to run it",
    "join.howPipe": "Paste into a shell",
    "join.howDownload": "Download, check, run",
    "join.howDownloadHint": "For routers and serial consoles, where a paste can lose characters: the file is downloaded first, sh -n checks its syntax, and the script verifies its own checksum before doing anything. Pasting the script's text into a terminal is not supported.",
    "join.wgetLabel": "Without curl (stock OpenWrt has wget):",
    "join.checkTitle": "Test first without using the command",
    "join.checkBody": "--check does everything up to the registration and uses no token: it says which shell, HTTP tool, SSH client (OpenSSH or Dropbear) and service manager it found, checks this machine's SSH server and its host key with a strict handshake, and checks that it can reach Telepy's gateway (including whether SSH keepalives work on that build).",
    "join.flow.s1": "Looks at what the device has: shell, HTTP tool, SSH client (OpenSSH or dbclient), service manager",
    "join.flow.s2": "Reads the SSH server's host key and verifies it with a strict handshake",
    "join.flow.s3": "Checks that the Telepy gateway answers, pins its host key and tests keepalives",
    "join.flow.s4": "Creates the tunnel key and registers {device} with the one-time command",
    "join.flow.s5": "Adds Telepy's key where this SSH server reads keys for {account} (append only)",
