    "settings.commandsRulesTitle": "Site-wide rules",
    "settings.commandsRulesBody": "{count} site-wide rules. Add, change and test them on the Site command rules page.",
    "settings.commandsRulesOpen": "Open site command rules",
    "siteSettings.command_approval_timeout.label": "Approval wait (seconds)",
    "siteSettings.command_approval_timeout.description": "How long a command that needs approval waits for the owner or an Admin. When nobody answers in time it counts as a denial and the line is cancelled. 30 to 86400.",
    "siteSettings.terminal_detach_max_secs.label": "Keep detached terminals for at most",
    "siteSettings.terminal_detach_max_secs.description": "When a browser drops (network switch, sleeping laptop, reload), its web terminal shell may wait this long for the same person to come back. Everyone picks their own time in Preferences (the default is to end at once); the shorter of the two applies, and a tunnel can be set to always end at once. 0 turns the feature off. Up to 86400.",
    "settings.groupSignin": "Sign-in",
    "settings.signinBanner": "How the sign-in pages look, how long a sign-in lasts and which second factors every account must have. Lifetime changes apply to sign-ins and renewals from now on; current sessions keep their remaining time until their next renewal.",
    "settings.unitLabel": "Unit",
    "settings.unitSeconds": "seconds",
    "settings.unitMinutes": "minutes",
    "settings.unitHours": "hours",
    "settings.unitDays": "days",
    "siteSettings.signin_lifetime.label": "Stay signed in for",
    "siteSettings.signin_lifetime.description": "How long a sign-in lasts without any visit. Every visit extends it (an open tab renews the session in the background), so people who use Telepy regularly stay signed in; after this long away they sign in again. Signing out ends the session at once. 5 minutes to 365 days.",
    "siteSettings.signin_access_lifetime.label": "Access token lifetime",
    "siteSettings.signin_access_lifetime.description": "How long each short-lived access token is valid before the browser renews it with the sign-in session. The renewal is automatic and invisible; shorter means a leaked token is usable for less time. 1 minute to 24 hours.",
    "siteSettings.signin_page_style.label": "Sign-in page",
    "siteSettings.signin_page_style.description": "/login, where everyone signs in.",
    "siteSettings.signin_oauth_style.label": "App connection sign-in page",
    "siteSettings.signin_oauth_style.description": "/oauth/login, shown when an MCP app asks to connect and the person isn't signed in yet. The discreet look keeps the app's name and where it returns to; the permissions it asks for are listed after signing in, on the consent page.",
    "siteSettings.signin_cli_style.label": "CLI sign-in page",
    "siteSettings.signin_cli_style.description": "The same /oauth/login, shown when someone runs telepy login in a terminal and the browser isn't signed in yet. The discreet look keeps the CLI's name and the computer it signs in from; the permissions it asks for are listed after signing in.",
    "siteSettings.signin_consent_style.description": "/oauth/authorize, where a signed-in person approves an MCP app or telepy login. Both looks list the app, where it returns, the permissions and the tunnels; the discreet look leaves out the connection diagram and steps. The page telepy login shows once it is signed in follows this look too.",
    "siteSettings.signin_consent_style.label": "Approval page (apps and the CLI)",
    "siteSettings.signin_page_message.label": "Lines on the discreet page",
    "siteSettings.signin_page_message.description": "Typed under Telepy, one line at a time: up to 6 lines of 80 characters. One line is typed and stays; two or more are typed, erased and replaced in turn. Anyone can read them before signing in, so keep internal details out.",
