    "deviceInstall.info.namesBody": "Every service, file and container Telepy installs for this tunnel is named after {id}. The id carries no user name, server or tunnel name, and renaming the tunnel never touches the device. Search the id on the tunnels page to find the tunnel a device's service belongs to.",
