    "deviceInstall.info.recordTitle": "What Telepy records",
    "deviceInstall.info.recordBody": "The install id, and what the last check found: services, the running ssh, crontab lines, files. It is checked after a one-command join, once a week while the device is online, and when you press Check again. Deleting the tunnel uses it to clean up, and never touches anything that connects to another server.",
