    "about.disclaimer": "Disclaimer",
    "about.disclaimerDescription": "Please read this before you connect a device or give anything access.",
    "about.disclaimerLicence": "Licence (AGPL-3.0)",
    "about.disclaimer.asIsTitle": "Provided as is, with no warranty",
    "about.disclaimer.asIsBody": "Telepy is free software under the AGPL-3.0 and is provided “as is”, without warranty of any kind, express or implied, including merchantability, fitness for a particular purpose and non-infringement. To the extent the law allows, its authors and contributors are not liable for any damage that comes from using it or being unable to use it, including lost data, downtime, a compromised system or financial loss (AGPL-3.0 sections 15 and 16).",
    "about.disclaimer.machinesTitle": "You are working on real machines",
    "about.disclaimer.machinesBody": "The terminal, file manager, remote desktop, remote browser, toolbox snippets and SSH forwards act directly on your devices and the machines on their networks. Deleting, overwriting, shutting down or changing permissions and firewalls usually cannot be undone. Check which machine and which account you are on before you act, and keep your own backups. Command rules, step-up confirmation and recordings help prevent mistakes; they are not a security boundary and will not catch every dangerous action.",
    "about.disclaimer.authorizedTitle": "Only connect what you are allowed to use",
    "about.disclaimer.authorizedBody": "Connect only devices and networks that you own or have explicit permission to access. Scanning networks, jumping to other hosts or forwarding ports on systems you are not authorised to use may break computer misuse laws, such as the US Computer Fraud and Abuse Act or the UK Computer Misuse Act, and your organisation's policies. That responsibility is yours, not Telepy's or its authors'.",
    "about.disclaimer.credentialsTitle": "Keys, tokens and sign-ins are as good as your password",
    "about.disclaimer.credentialsBody": "Your SSH keys, API tokens (tpt_…), CLI sign-ins and MCP app connections can each reach your devices with your permissions, and what they do is done in your name. Guard them like passwords: never paste them into chats, code repositories or public CI logs; give each one only the scopes, tunnels and lifetime it needs; revoke whatever you no longer use.",
    "about.disclaimer.agentsTitle": "MCP agents act on what they read",
    "about.disclaimer.agentsBody": "An MCP app you connect can run commands, read and write files and drive a browser on your devices within the scopes you approved. AI can misunderstand you, produce wrong commands, or be steered by instructions hidden in a web page, a file or command output (prompt injection) into doing something you never asked for. Connect only apps you trust, grant the narrowest scopes and tunnels, add approval rules for risky commands and check what they did on the AI activity page. You answer for what an agent does with the access you gave it.",
    "about.disclaimer.sharingTitle": "Sharing hands over a key",
    "about.disclaimer.sharingBody": "Sharing a tunnel, granting ADMIN or allowing a login account lets that person work on the device as that account. Share only with people you trust, set an end date where you can, and review who has access from time to time.",
    "about.disclaimer.operatorsTitle": "If you run this Telepy server",
    "about.disclaimer.operatorsBody": "Administrators who host Telepy are responsible for securing the server (SECRET_KEY, TLS, updates, backups), for the accounts and permissions they hand out, and for complying with the privacy laws that apply to them, such as the GDPR. Telepy keeps IP addresses, sign-in history, audit logs and, on tunnels that record, terminal output; tell your users what is recorded and how long it is kept.",
    "about.disclaimer.closing": "By using Telepy you confirm that you understand these risks and take responsibility for how you use it. This notice adds to the licence; it does not change it.",
