    "tunnelName.rules": "Becomes the SSH host name: letters, digits, '.', '_' and '-', starting with a letter or digit (up to 63). Upper and lower case count as the same name.",
    "tunnelName.rulesJoin": "Leave it empty to use the device's hostname. It becomes the SSH host name: letters, digits, '.', '_' and '-', starting with a letter or digit (up to 63); upper and lower case count as the same name.",
    "tunnelName.why": "Why?",
    "tunnelName.whyTitle": "Why these rules",
    "tunnelName.why1": "The name is the SSH host name: {ssh}, {cli} and the generated SSH config use it as it is.",
    "tunnelName.why2": "In an SSH config a space splits one name into two, and SSH refuses host names with spaces or shell characters on the command line. {chars} mean something of their own there.",
    "tunnelName.why3": "Telepy itself uses '@' and ':': {at}, {colon}.",
    "tunnelName.why4": "SSH turns host names into lower case when it connects, so {upper} and {lower} would reach the same tunnel. That's why only one of them can exist.",
    "tunnelName.whySource": "These follow OpenSSH's own rules for host names.",
    "tunnelName.err.empty": "Give it a name.",
    "tunnelName.err.tooLong": "Use at most 63 characters.",
    "tunnelName.err.firstChar": "Start with a letter or a digit.",
    "tunnelName.err.chars": "Only letters, digits, '.', '_' and '-'. Not allowed: {chars}",
    "tunnelName.space": "space",
    "tunnelName.whitespace": "tab or line break",
    "tunnelName.use": "Use “{name}”",
    "tunnelName.taken": "Another tunnel already has this name (upper and lower case count as the same).",
